        } else {
            $c.stf.showObj(btn_secu, false);
        }
    } else {
        btn_IsuNew.src = "../img/btn_IsuNew_d.gif";
        btn_IsuNew.setDisabled(true);
        $c.stf.showObj(lab_btn, true);
        $c.stf.showObj(btn_secu, false);
    }
};


