scwin.img_SPAC_LAPS_MERGE_ISUR_NM_onclick = function() {
    // SPAC소멸합병상장의 경우만 선택  jackal_22.02.11
    if ($c.stf.getObjectValue(cmb_LIST_CLSS_CD) != "31") {
        $c.win.alert("상장구분이 [SPAC-소멸합병]의 경우만 선택하세요.");
