scwin.dts_Corp_OnLoadCompleted = function(rowcount) {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (scwin.vBzProcsNo == "") {
        buttonSet.setInsertStatus();
        scwin.fn_initForm('C');
    } else {
        scwin.fn_initForm('X');
        if ($c.stf.getObjectValue(edt_LIST_DD) > vCurDate) {
            buttonSet.setUpdateStatus();
        } else {
            buttonSet.setErrorStatus(); //disable 시킨다.

        }
    }
    if ($c.stf.getObjectValue(txb_LIST_NO) != "") {
        img_LIST_NO.src = "../img/btn_LstNoCrt_d.gif";
        img_LIST_NO.setDisabled(true);
    }

    //gAfStdIndCd = dts_Corp.NameValue(1, "AF_STD_IND_CD");

    if ($c.stf.getObjectValue(txb_FSS_UNQ_NO) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-0025", ""));
        buttonSet.setErrorStatus(); //disable 시킨다.

    }
    /*2010.02.17 금감원 코드가 없을경유 입력할 수 이도록 해준다.
    if (getObjectValue(txb_FSS_UNQ_NO) == "") {
    	txb_FSS_UNQ_NO.readOnly = false;
    }
    */
    if (dts_Corp.getCellData(1, "SPOT_ISU_TRD_MKT_TP_CD") == "2") {
        $c.stf.showObj(panel_pharma_bio_com_yn, true); //제약바이오 기업여부 
        $c.stf.showObj(pnl_LIST_INVSTG_COND, true); //상장심사요건 항목
        $c.stf.showObj(pnl_segment, true);
    } else {
        $c.stf.showObj(panel_pharma_bio_com_yn, false); //제약바이오 기업여부 
        $c.stf.showObj(pnl_LIST_INVSTG_COND, false); //상장심사요건 항목
        $c.stf.showObj(pnl_segment, false);
    }
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = async function() {
    $c.lc.fn_alertMsg('S');
    scwin.fn_parentRefresh();

    //20100910 (2616) 회사정보 저장 후 '상장종목신규'버튼 활성화
    scwin.fn_btnShow(scwin.vBzProcsNo);
    if (buttonSet.status == "U") {
        var parentWin = $c.frame.path("../");
        parentWin.dts_List.setFocusedCell(scwin.rowPos, 0);
    }
    if (buttonSet.status == "D") {
        // 삭제처리의 응답인 경우
        if (js_market == "2") {
            //저장시 소속부변경 알림 팝업 
            $c.win.alert("소속부변경_STF05234 화면에서 확인하여 주십시오");
        }
        await $c.frame.CloseFrame();
    } else {
        scwin.fn_read_sync();
        if (js_market == "2") {
            //저장시 소속부변경 알림 팝업 
            $c.win.alert("소속부변경_STF05234 화면에서 확인하여 주십시오");
        }
    }
};
