scwin.gform_onload = function() {
    $c.stf.showObj(panel_SPAC_LAPS_MERGE_ISUR_CD, false); // jackal_22.02.11
    $c.stf.showObj(panel_HDCOM_ISUR_CD, false);
    if (js_market == "1") {
        $c.stf.showObj(panel_KOSDAQ, false);
        $c.stf.showObj(panel_KOSDAQ1, false);
        $c.stf.showObj(panel_KSE, true);
        $c.stf.showObj(panel_konex_secu_list_methd_tp_cd, false);
        $c.stf.showObj(lbl_leadcom, true);
        $c.stf.showObj(lbl_specifiedadvisor, false);
        $c.stf.showObj(pan_konex_lp, false);
        $c.stf.showObj(lbl_KONEX_SECT, false);
        $c.stf.showObj(cmb_SPECL_LIST_TP_CD, false);
        $c.stf.showObj(img_LEADCOM_MBR_NO, true);
        $c.stf.showObj(pnl_segment, false);
    } else if (js_market == "2") {
        $c.stf.showObj(panel_KOSDAQ, true);
        $c.stf.showObj(panel_KOSDAQ1, true);
        $c.stf.showObj(panel_KSE, false);
        $c.stf.showObj(panel_konex_secu_list_methd_tp_cd, false);
        $c.stf.showObj(lbl_leadcom, true);
        $c.stf.showObj(lbl_specifiedadvisor, false);
        $c.stf.showObj(pan_konex_lp, false);
        $c.stf.showObj(lbl_KONEX_SECT, false);
        $c.stf.showObj(cmb_SPECL_LIST_TP_CD, false);
        $c.stf.showObj(img_LEADCOM_MBR_NO, true);
        $c.stf.showObj(pnl_segment, true);
    } else if (js_market == "6") {
        $c.stf.showObj(panel_KOSDAQ, true);
        $c.stf.showObj(panel_KOSDAQ1, true);
        $c.stf.showObj(panel_KSE, false);
        $c.stf.showObj(panel_SPAC_LAPS_MERGE_ISUR, false); //SPAC소멸합병 jackal_22.02.11
        $c.stf.showObj(panel_hdcom, false); //지주회사
        $c.stf.showObj(panel_dirctlist, false); //직상장법인여부
        $c.stf.showObj(panel_sme, false); //중소기업여부
        $c.stf.showObj(panel_peplstk, false); //국민주여부
        $c.stf.showObj(panel_spac_yn, false); //스팩여부
        $c.stf.showObj(panel_spac, false);
        $c.stf.showObj(panel_konex_secu_list_methd_tp_cd, true);
        $c.stf.showObj(lbl_leadcom, false);
        $c.stf.showObj(lbl_specifiedadvisor, true);
        $c.stf.showObj(pan_konex_lp, true);
        $c.stf.showObj(lbl_KONEX_SECT, true);
        $c.stf.showObj(cmb_SPECL_LIST_TP_CD, true);
        $c.stf.showObj(img_LEADCOM_MBR_NO, false);
        $c.stf.showObj(pnl_segment, false);
    } else {
        scwin.pJsMarket = '1';
        $c.stf.showObj(img_LEADCOM_MBR_NO, true);
    }
    $c.cm.PanelToGroupBox(panel_Top);
    $c.libRoundPanel.PanelToGroupBox(panel_Item);
    $c.elw.fn_searchCode();
    scwin.fn_SetComboCode();
    var parentWin = $c.frame.path("../");
    scwin.vBzProcsNo = parentWin.scwin.clickBzProcsNo;
    scwin.rowPos = parentWin.dts_List.getFocusedRowIndex();

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDsclInfo(btn_Dscl, fn_dscl); // 안내문작성

    //20100910 (2616) 회사정보 저장 후 '상장종목신규'버튼 활성화
    scwin.fn_btnShow(scwin.vBzProcsNo);
    if (scwin.vBzProcsNo != "") {
        scwin.fn_read_sync();
        txb_SearchCd.setValue(dts_Corp.getCellData(1, "ISUR_CD"));
        txb_SearchNm.setValue(dts_Corp.getCellData(1, "COM_NM"));
        cmb_SECUGRP_ID.setDisabled(true);

        //spac 여부에 따른 존립기간 _20100528
        if ($c.stf.getObjectValue(cmb_SPAC_YN) == "Y") {
            $c.stf.showObj(panel_spac, true);
        }
    } else {
        //존립기간disabled _20100528
        $c.stf.showObj(panel_spac, false);
        $c.stf.setObjectValue(cmb_SECUGRP_ID, $c.stf.getObjectValue(parentWin.cmb_NEW_SECUGRP_ID)); //부모창에서 증권그룹값이 가져온다.
        $c.stf.setObjectValue(cmb_SPOT_ISU_TRD_MKT_TP_CD, scwin.pJsMarket);
        buttonSet.setInsertStatus();
    }
};
